    name = "asus-rog-gladius-ii",
    sensitivity = -0.7,
})

local mainMod = "SUPER" -- Sets "Windows" key as main modifier
local shiftMod = "SHIFT + SUPER" -- Sets "Windows + Shift" as secondary modifier

hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exit())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager .. " --new-window"))
hl.bind(mainMod .. " + Y", hl.dsp.exec_cmd(terminal .. " yazi"))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu .. " --show drun"))
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd(menu .. " --show run -I"))
hl.bind(mainMod .. " + P", hl.dsp.window.pin())
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(web_browser))
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(terminal .. " lazydocker"))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal .. " --class trader /home/maxy/Tools/tradercli/trader.sh"))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd(terminal .. " --class btop btop"))
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(code))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("pidof hyprlock || hyprlock"))
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("rofi -show combi -combi-modes \"window, run, ssh\" -modes combi"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("wlogout --protocol layer-shell"))
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd("hyprpicker -f hex -a"))
hl.bind(mainMod .. " + U", hl.dsp.focus({ workspace = "11 && sleep 1 && hyprctl dispatch dpms off" }))
hl.bind(mainMod .. " + I", hl.dsp.exec_raw("hyprctl dispatch dpms on && sleep 4 && hyprlock"))
hl.bind("Print", hl.dsp.exec_cmd("hyprshot -m window --clipboard"))
hl.bind(shiftMod .. " + PRINT", hl.dsp.exec_cmd("hyprshot -m region --clipboard"))
hl.bind(mainMod .. " + H", hl.dsp.exec_cmd("hyprctl keyword monitor HDMI-A-1, 3840x2160@60, 0x0, auto, bitdepth, 10, cm, hdr, sdrbrightness, 1.0, sdrsaturation, 0.98"))
hl.bind(mainMod .. " + G", hl.dsp.exec_cmd("hyprctl keyword monitor HDMI-A-1, 3840x2160@60, 0x0, auto, bitdepth, 10, cm, hdr, sdrbrightness, 1.1, sdrsaturation, 0.98"))
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.exec_cmd("hyprctl keyword monitor HDMI-A-1, 3840x2160@60, 0x0, auto"))

